// Build the Gemini image-editing request from the app's multipart upload.
// Expected form fields: photo (file), logo (file, optional),
// description, company_name, company_details.
const item = $input.first();
const body = item.json.body || item.json;

if (!item.binary || !item.binary.photo) {
  throw new Error('No "photo" file was uploaded');
}

const description = (body.description || '').toString().trim();
const companyName = (body.company_name || '').toString().trim();
const companyDetails = (body.company_details || '').toString().trim();
const hasLogo = !!(item.binary && item.binary.logo);

const photoBuffer = await this.helpers.getBinaryDataBuffer(0, 'photo');
const parts = [
  {
    inlineData: {
      mimeType: item.binary.photo.mimeType || 'image/jpeg',
      data: photoBuffer.toString('base64'),
    },
  },
];

if (hasLogo) {
  const logoBuffer = await this.helpers.getBinaryDataBuffer(0, 'logo');
  parts.push({
    inlineData: {
      mimeType: item.binary.logo.mimeType || 'image/png',
      data: logoBuffer.toString('base64'),
    },
  });
}

let prompt = 'You are a professional marketing photo editor. ' +
  'The FIRST image is the source photo uploaded by the user. ';
if (hasLogo) {
  prompt += 'The SECOND image is the company logo. ';
}
prompt += 'Create a new, polished marketing version of the source photo based on this instruction: "' +
  (description || 'enhance the photo for professional marketing use') + '". ';
if (hasLogo) {
  prompt += 'Place the company logo tastefully in a corner of the image, clearly visible but not covering the main subject. ';
}
if (companyName) {
  prompt += 'Add the company name "' + companyName + '" as clean, professional text on the image. ';
}
if (companyDetails) {
  prompt += 'Also include these company details in smaller, legible text (for example along the bottom edge): "' + companyDetails + '". ';
}
prompt += 'Keep all text spelled exactly as given, sharp and readable. Return only the final image.';

parts.push({ text: prompt });

return [{
  json: {
    requestBody: {
      contents: [{ parts }],
      generationConfig: { responseModalities: ['IMAGE'] },
    },
  },
}];

// Pull the generated image out of the Gemini response and hand it back as binary.
const resp = $input.first().json;
const parts = resp?.candidates?.[0]?.content?.parts || [];
const imagePart = parts.find((p) => p.inlineData && p.inlineData.data);

if (!imagePart) {
  const reason = resp?.candidates?.[0]?.finishReason || resp?.error?.message || 'unknown';
  throw new Error('Gemini returned no image (reason: ' + reason + ')');
}

const buffer = Buffer.from(imagePart.inlineData.data, 'base64');
const binary = await this.helpers.prepareBinaryData(
  buffer,
  'branded-photo.png',
  imagePart.inlineData.mimeType || 'image/png'
);

return [{ json: { success: true }, binary: { data: binary } }];
